
insert into public.intelligence_records (slug,content_type,headline,source_title,executive_summary,source_facts,detailed_analysis,practical_implications,publication_date,event_date,effective_date,jurisdiction_id,regime_id,authority_id,affected_entities,affected_sectors,legal_provisions,case_number,penalty_amount,penalty_currency,legal_status,violation,circumvention_methods,control_failures,source_url,source_publisher,verification_status,priority,tags) values
('eu-14th-package-russia','sanctions_development','EU adopts 14th Russia sanctions package, introducing "best efforts" duty for subsidiaries and LNG transshipment ban','Council Regulation (EU) 2024/1745 of 24 June 2024 amending Regulation (EU) No 833/2014',
'The 14th package extends EU restrictions on Russia, notably requiring EU parent companies to use best efforts to ensure non-EU subsidiaries do not undermine sanctions, banning EU-port transshipment of Russian LNG, and prohibiting EU entities outside Russia from connecting to the SPFS messaging system.',
'Council Regulation (EU) 2024/1745 was adopted on 24 June 2024 and published in the Official Journal the following day. It amends Regulation (EU) No 833/2014. Measures include: an obligation on EU operators to undertake best efforts to ensure that legal persons they own or control outside the Union do not participate in activities undermining the restrictive measures (new Article 8a); a prohibition on reloading services in EU territory for Russian LNG transshipment; a prohibition on connecting to the SPFS (the Central Bank of Russia''s financial messaging service); and expanded "No Russia" clause obligations.',
'The "best efforts" obligation moves group-wide sanctions governance from good practice toward a legal duty. The Regulation does not prescribe what constitutes best efforts; Commission FAQs are the primary interpretive aid. The SPFS ban targets a known alternative to SWIFT used to route payments outside Western messaging infrastructure.',
'ANALYSIS — EU banks and corporates with non-EU subsidiaries should document group-wide sanctions policies, screening coverage and escalation lines that reach those subsidiaries. Payment operations teams should confirm no direct or indirect SPFS connectivity exists outside Russia. Uncertainty remains about the evidential standard for "best efforts"; a legal opinion is advisable for complex group structures.',
'2024-06-25','2024-06-24','2024-06-25',(select id from jurisdictions where code='EU'),(select id from regimes where slug='russia'),(select id from authorities where slug='eu-council'),
'{"EU parent companies","Non-EU subsidiaries","LNG terminals"}','{"Banking","Energy","Shipping"}','{"Regulation (EU) 2024/1745","Regulation (EU) No 833/2014, Art. 8a","Regulation (EU) No 833/2014, Art. 5ac"}',
null,null,null,'in_force',null,'{}','{}','https://eur-lex.europa.eu/eli/reg/2024/1745/oj','EUR-Lex / Official Journal of the EU','verified',true,'{"best efforts","SPFS","LNG","subsidiaries"}'),

('eu-16th-package-russia','sanctions_development','EU 16th Russia package targets shadow fleet vessels and further restricts Russian banks','Council Regulation (EU) 2025/395 of 24 February 2025 amending Regulation (EU) No 833/2014',
'Adopted on the third anniversary of the full-scale invasion, the 16th package adds vessels to the port-access and services ban list, extends transaction bans to additional Russian and third-country banks, and adds new export restrictions.',
'Council Regulation (EU) 2025/395 was adopted on 24 February 2025. The Council''s press release states the package lists further vessels subject to port access and service bans as part of the shadow fleet, adds financial institutions to the transaction ban, and introduces further import and export restrictions. Parallel listings of individuals and entities were adopted under Regulation (EU) No 269/2014.',
'The continued expansion of the vessel list reflects the EU''s focus on maritime circumvention of the oil price cap. Banks listed under the transaction ban include institutions in third countries, increasing correspondent banking risk beyond Russia itself.',
'ANALYSIS — Trade finance and maritime insurers should refresh vessel screening against Annex XLII and review exposure to newly listed third-country banks. Confirm the exact annex entries against the Official Journal text before relying on any summary.',
'2025-02-24','2025-02-24','2025-02-25',(select id from jurisdictions where code='EU'),(select id from regimes where slug='russia'),(select id from authorities where slug='eu-council'),
'{"Shadow fleet vessels","Third-country banks"}','{"Shipping","Banking","Insurance"}','{"Regulation (EU) 2025/395","Regulation (EU) No 833/2014"}',
null,null,null,'in_force',null,'{"Shadow fleet vessels","Flag hopping"}','{}','https://www.consilium.europa.eu/en/press/press-releases/2025/02/24/russia-s-war-of-aggression-against-ukraine-eu-adopts-its-16th-package-of-economic-and-individual-sanctions/','Council of the EU','verified',false,'{"shadow fleet","vessels","banks"}'),

('cjeu-rosneft-c72-15','case_law','CJEU upholds validity of EU sectoral sanctions on Rosneft and confirms Member State criminal penalties','Judgment of the Court (Grand Chamber), 28 March 2017, PJSC Rosneft Oil Company v HM Treasury and Others, C-72/15',
'On a preliminary reference from the English High Court, the Grand Chamber held it has jurisdiction to review the legality of CFSP decisions imposing restrictive measures on persons, upheld the validity of the contested Russia sectoral measures, and confirmed Member States may impose criminal penalties for breaches.',
'Case C-72/15, judgment of 28 March 2017 (Grand Chamber). Referring court: High Court of Justice (England & Wales). The Court found that it has jurisdiction to give preliminary rulings on the validity of CFSP acts providing for restrictive measures against natural or legal persons; the examination disclosed nothing affecting the validity of Decision 2014/512/CFSP or relevant provisions of Regulation No 833/2014; and the principle of legal certainty does not preclude Member States from imposing criminal penalties for infringements before the meaning of a provision has been clarified by the Court. Document type: final judgment.',
'Rosneft remains a foundational authority on the reach of CJEU review over CFSP-based sanctions and on Member State enforcement discretion. It also addressed the interpretation of terms such as "financial assistance" in the context of GDR issuance.',
'ANALYSIS — Compliance teams should not treat interpretive ambiguity in EU sanctions provisions as a defence; national authorities may prosecute even where the CJEU has not yet clarified a term. Where wording is ambiguous, adopt a conservative reading and document reasoning.',
'2017-03-28','2017-03-28',null,(select id from jurisdictions where code='EU'),(select id from regimes where slug='russia'),(select id from authorities where slug='cjeu'),
'{"PJSC Rosneft Oil Company","HM Treasury","Financial Conduct Authority"}','{"Energy","Capital Markets"}','{"Decision 2014/512/CFSP","Regulation (EU) No 833/2014","Art. 275 TFEU"}',
'C-72/15',null,null,'final_judgment',null,'{}','{}','https://curia.europa.eu/juris/liste.jsf?num=C-72/15','CURIA','verified',false,'{"preliminary reference","validity","legal certainty"}'),

('cjeu-neves-77-c351-22','case_law','CJEU confirms jurisdiction over national penalties for breach of EU brokering prohibitions (Neves 77 Solutions)','Judgment of the Court (Grand Chamber), 10 September 2024, Neves 77 Solutions SRL v Agenţia Naţională de Administrare Fiscală, C-351/22',
'The Grand Chamber held that it has jurisdiction to interpret CFSP decisions on a preliminary reference where a national penalty is imposed for breach of a restrictive measure, and addressed proportionality of national penalties, including confiscation, for brokering services related to military technology for Russia.',
'Case C-351/22, judgment of 10 September 2024 (Grand Chamber), on a reference from a Romanian court. The case concerned a penalty imposed on a Romanian company for providing brokering services in connection with military technology linked to Russia, in breach of Decision 2014/512/CFSP. The Court extended its jurisdiction under the preliminary reference procedure to interpret CFSP decisions in this context and addressed the compatibility of the penalty with the principle of proportionality. Document type: final judgment.',
'The ruling strengthens uniform interpretation of CFSP-based prohibitions across Member States and signals that national penalties must remain effective, proportionate and dissuasive.',
'ANALYSIS — Brokering and intermediary services are a live enforcement area. Firms facilitating transactions — even without handling goods — should screen for military-list items and dual-use goods. Confirm the precise holdings against the full judgment text before citing.',
'2024-09-10','2024-09-10',null,(select id from jurisdictions where code='EU'),(select id from regimes where slug='russia'),(select id from authorities where slug='cjeu'),
'{"Neves 77 Solutions SRL"}','{"Defence","Brokering"}','{"Decision 2014/512/CFSP, Art. 2","Art. 24 TEU","Art. 275 TFEU"}',
'C-351/22',null,null,'final_judgment',null,'{}','{}','https://curia.europa.eu/juris/liste.jsf?num=C-351/22','CURIA','pending_review',false,'{"brokering","proportionality","CFSP jurisdiction"}'),

('uksc-shvidler','case_law','UK Supreme Court dismisses Shvidler appeal, upholding designation under Russia regulations','Shvidler v Secretary of State for Foreign, Commonwealth and Development Affairs [2025] UKSC 30',
'The Supreme Court, by majority, dismissed the appeal of Eugene Shvidler against his designation under the Russia (Sanctions) (EU Exit) Regulations 2019, finding the designation was a proportionate interference with his Convention rights. Lord Leggatt dissented.',
'Judgment handed down 30 July 2025. The appellant, a British citizen, was designated in March 2022 on the basis of his association with Roman Abramovich and Evraz plc. The High Court and Court of Appeal had dismissed his challenge under s.38 of the Sanctions and Anti-Money Laundering Act 2018. The Supreme Court majority dismissed the further appeal, giving weight to the executive''s assessment in foreign policy and national security matters. Document type: final judgment.',
'The judgment confirms a high degree of judicial deference to ministerial designation decisions under SAMLA and makes successful designation challenges in the UK courts difficult. The dissent provides a counterpoint on the intensity of proportionality review.',
'ANALYSIS — UK designations should be treated as durable; firms should not anticipate delisting through litigation when planning exposure exits. Association-based designation criteria remain a material risk for counterparties linked to designated persons.',
'2025-07-30','2025-07-30',null,(select id from jurisdictions where code='UK'),(select id from regimes where slug='russia'),(select id from authorities where slug='uksc'),
'{"Eugene Shvidler","Roman Abramovich","Evraz plc"}','{"Metals & Mining"}','{"Sanctions and Anti-Money Laundering Act 2018, s.38","Russia (Sanctions) (EU Exit) Regulations 2019, reg. 6","ECHR Art. 8; A1P1"}',
'[2025] UKSC 30',null,null,'final_judgment',null,'{}','{}','https://www.supremecourt.uk/cases/uksc-2024-0010','UK Supreme Court','pending_review',true,'{"designation challenge","proportionality","association"}'),

('ofac-binance-2023','enforcement_action','OFAC settles with Binance for $968.6 million over apparent violations across multiple sanctions programmes','OFAC Settles with Binance Holdings, Ltd. for $968,618,825 Related to Apparent Violations of Multiple Sanctions Programs',
'OFAC''s settlement formed part of a coordinated resolution with DOJ and FinCEN. OFAC found Binance''s platform matched US persons with users in sanctioned jurisdictions, including Iran, Cuba, Syria and occupied regions of Ukraine.',
'On 21 November 2023 OFAC announced a $968,618,825 settlement with Binance Holdings, Ltd. for 1,667,153 apparent violations of multiple sanctions programmes. OFAC stated the matching engine facilitated trades between US users and users in sanctioned jurisdictions. Senior management was aware of US users on the platform and took steps that OFAC characterised as obscuring their presence. The case was determined to be egregious and not voluntarily self-disclosed. Binance agreed to a five-year compliance monitorship (through the DOJ/FinCEN resolution). Status: civil settlement — no admission of liability is implied by OFAC settlements unless stated.',
'The case is a reference point for virtual asset service providers on IP-based geofencing, KYC refresh, and the risk of tolerating US-nexus users while serving sanctioned jurisdictions.',
'ANALYSIS — Crypto platforms and banks providing services to VASPs should test geolocation controls (IP, device, KYC nationality) and confirm that matching engines cannot pair US persons with sanctioned-jurisdiction users. Banks should factor counterparty sanctions-compliance maturity into VASP onboarding.',
'2023-11-21','2023-11-21',null,(select id from jurisdictions where code='US'),(select id from regimes where slug='multi'),(select id from authorities where slug='ofac'),
'{"Binance Holdings, Ltd."}','{"Virtual Assets"}','{"IEEPA","Iranian Transactions and Sanctions Regulations","Cuban Assets Control Regulations","Syrian Sanctions Regulations"}',
'OFAC Enforcement Release 20231121',968618825,'USD','settlement','Facilitating transactions between US persons and users in sanctioned jurisdictions',
'{"VPN use to evade IP geoblocking","Incomplete KYC enabling users to misstate jurisdiction"}','{"Ineffective geofencing","Management tolerance of US users","Absence of sanctions screening on matching engine"}',
'https://ofac.treasury.gov/recent-actions/20231121','US Treasury OFAC','verified',true,'{"crypto","VASP","geofencing","egregious"}'),

('ofac-gva-capital-2024','enforcement_action','OFAC imposes $216 million penalty on GVA Capital for managing investment of designated Russian oligarch','OFAC Imposes $215,988,868 Penalty on GVA Capital Ltd. for Violating Russia and Ukraine-Related Sanctions',
'OFAC penalised a San Francisco venture capital firm for managing an investment for a designated individual through a network of nominees and trust structures, and for failing to comply with a subpoena.',
'On 12 June 2024 OFAC issued a Penalty Notice of $215,988,868 to GVA Capital Ltd. OFAC determined that GVA Capital managed an investment on behalf of Suleiman Kerimov, a designated individual, after his designation, and that GVA Capital knew Kerimov was the ultimate owner of the funds despite their being held via nominee and trust arrangements. OFAC also found GVA Capital failed to comply with an administrative subpoena. Status: penalty notice (OFAC determination; not a settlement).',
'The case demonstrates OFAC''s willingness to impose the statutory maximum where it finds wilful conduct, and its focus on the gatekeeper role of investment advisers in the private funds space.',
'ANALYSIS — Fund managers and private banks should look through nominee and trust structures to identify beneficial owners and controllers, not only formal holders. Interests of blocked persons must be blocked and reported, irrespective of the 50% rule mechanics of intermediate vehicles.',
'2024-06-12','2024-06-12',null,(select id from jurisdictions where code='US'),(select id from regimes where slug='russia'),(select id from authorities where slug='ofac'),
'{"GVA Capital Ltd.","Suleiman Kerimov"}','{"Venture Capital","Asset Management"}','{"Ukraine-/Russia-Related Sanctions Regulations, 31 CFR part 589","Russian Harmful Foreign Activities Sanctions Regulations, 31 CFR part 587"}',
'OFAC Enforcement Release 20240612',215988868,'USD','penalty_notice','Dealing in property and interests in property of a blocked person',
'{"Nominee shareholders","Trust structures obscuring beneficial ownership"}','{"Failure to block known interest of designated person","Non-compliance with OFAC subpoena"}',
'https://ofac.treasury.gov/recent-actions/20240612','US Treasury OFAC','verified',true,'{"beneficial ownership","oligarch","private funds"}'),

('ofsi-wise-2023','enforcement_action','OFSI imposes £50,000 penalty on Wise Payments for withdrawal by company owned by a designated person','Financial sanctions enforcement action: Wise Payments Limited',
'OFSI imposed a civil monetary penalty on Wise Payments Limited after a company owned or controlled by a designated person withdrew £250 from its account via a debit card shortly after designation.',
'On 31 August 2023 OFSI published a penalty of £50,000 against Wise Payments Limited for a breach of regulation 11 of the Russia (Sanctions) (EU Exit) Regulations 2019. A company owned or controlled by a designated person was permitted to withdraw £250 cash from its Wise account after Wise had frozen the account but before its debit card was cancelled. OFSI found the breach was voluntarily disclosed but considered the case moderately severe given control weaknesses. Status: civil penalty.',
'Small-value breaches can still lead to public penalties in the UK. The case highlights the need for frozen-account controls to cover all payment channels, including cards.',
'ANALYSIS — Payment institutions should ensure an account freeze automatically suspends cards, direct debits and API access in real time. Control testing should include card-scheme authorisations, which may operate outside core banking freeze flags.',
'2023-08-31','2022-05-16',null,(select id from jurisdictions where code='UK'),(select id from regimes where slug='russia'),(select id from authorities where slug='ofsi'),
'{"Wise Payments Limited"}','{"Payments","E-money"}','{"Russia (Sanctions) (EU Exit) Regulations 2019, reg. 11","Policing and Crime Act 2017, s.146"}',
null,50000,'GBP','penalty_notice','Making funds available to an entity owned or controlled by a designated person',
'{}','{"Card controls not linked to account freeze","Manual freeze processes"}',
